import{_ as t,o as a,c as n,ak as i}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy technical acceptance checklist","description":"Christian owns technical acceptance. Use the technical design, database reference and player flow; this checklist does not define a second architecture.","frontmatter":{"title":"Chainy technical acceptance checklist","description":"Christian owns technical acceptance. Use the technical design, database reference and player flow; this checklist does not define a second architecture.","source":"docs/requirements/technical-requirements.md","category":"Requirements","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/requirements/technical-requirements.md","filePath":"content/docs/requirements/technical-requirements.md"}'),c={name:"content/docs/requirements/technical-requirements.md"};function s(r,e,o,l,d,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-technical-acceptance-checklist">Chainy technical acceptance checklist<a class="header-anchor" href="#chainy-technical-acceptance-checklist" aria-label="Link to this section">​</a></h1><p>Christian owns technical acceptance. Use the <a href="/Chainy-Docs/content/docs/technical-design.html">technical design</a>, <a href="/Chainy-Docs/content/docs/design/database-schema.html">database reference</a> and <a href="/Chainy-Docs/content/docs/design/app-flow.html">player flow</a>; this checklist does not define a second architecture.</p><p>Before the fixed November 3–6 beta:</p><ul><li>Pin the actual source revision, Unity version, Android settings and SQLite binding.</li><li>Route input to one active mode; prevent actions during scene load, pause, save and board resolution.</li><li>Preserve the source&#39;s responsibilities: UI presents, game managers run rules, Progress Manager coordinates data, Database Manager executes storage operations.</li><li>Verify Quiz, Wordle and BlockMatch rules using agreed correct/incorrect and end-state examples.</li><li>Validate the actual data schema, learner-code format and score/attempt meanings.</li><li>Demonstrate two-profile isolation, save/reload, failed-save recovery and repeat-safe result submission.</li><li>Verify offline teacher collection and a tested update procedure.</li><li>Record the actual device and performance observations; do not infer support from the editor.</li></ul><p>Unresolved implementation details belong on the existing CH-02/03/04 tasks. The old SQL/event framework and AI/classifier implementation requirements are retired. No game code or database was changed by this documentation revision.</p></div>',1)])])}const m=t(c,[["render",s]]);export{u as __pageData,m as default};
